<script setup lang="ts">
import {ref,onMounted,onUnmounted} from 'vue';
import {Search,ChevronRight,ArrowLeft,RefreshCw,ShieldCheck} from 'lucide-vue-next';
import {treeholeError,treeholeErrorCode,type TreeholePost,type TreeholeComment,type TreeholeReport,type TreeholeResult,type TreeholeModeration} from '../services/treehole';
const props=defineProps<{request:(action:string,body?:Record<string,unknown>)=>Promise<TreeholeResult>;initialTarget?:{postId:string;commentId?:string|null}|null}>();
const emit=defineEmits<{changed:[];expired:[]}>();
const tab=ref<'reports'|'content'|'history'>('reports'),reports=ref<TreeholeReport[]>([]),posts=ref<TreeholePost[]>([]),history=ref<TreeholeModeration[]>([]),query=ref(''),busy=ref(false),error=ref(''),notice=ref(''),more=ref(false);
const target=ref<{postId:string;commentId?:string|null;reportId?:string|null;reportReason?:string}|null>(null),post=ref<TreeholePost|null>(null),comment=ref<TreeholeComment|null>(null),comments=ref<TreeholeComment[]>([]),parentComment=ref<TreeholeComment|null>(null),removed=ref(false),reason=ref(''),decision=ref(''),confirm=ref(false);
const labels:Record<string,string>={remove:'删除内容',lock:'暂停整篇回复',unlock:'恢复整篇回复',ban:'禁言作者 7 天',dismiss:'无需处理',grant_moderator:'授予管理员'};
let alive=true,revision=0,requestId=crypto.randomUUID();
onUnmounted(()=>{alive=false;revision++});
async function run(work:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await work()}catch(e){if(alive){error.value=treeholeError(e);if(treeholeErrorCode(e)==='session_expired'||treeholeErrorCode(e)==='forbidden')emit('expired')}}finally{if(alive)busy.value=false}}
async function load(append=false){const version=++revision,kind=tab.value,rows=kind==='history'?history.value:posts.value,last=rows.at(-1);const result=await props.request(kind==='reports'?'admin.reports':kind==='content'?'admin.content':'admin.history',{...(kind==='content'?{query:query.value.trim()}:{}),...(append&&last?{beforeTime:last.createdAt,beforeId:last.id}:{})});if(!alive||version!==revision)return;
 if(kind==='reports'){reports.value=result.reports||[];more.value=false}else if(kind==='content'){const next=result.posts||[];posts.value=append?[...posts.value,...next.filter(p=>!posts.value.some(x=>x.id===p.id))]:next;more.value=next.length===20}else{const next=result.history||[];history.value=append?[...history.value,...next.filter(p=>!history.value.some(x=>x.id===p.id))]:next;more.value=next.length===30}}
function change(next:typeof tab.value){if(busy.value)return;tab.value=next;notice.value='';void run(()=>load())}
async function context(next:NonNullable<typeof target.value>){const result=await props.request('admin.context',next);if(!alive)return;target.value=next;post.value=result.post||null;comment.value=result.comment||null;comments.value=result.comments||[];parentComment.value=result.context||null;removed.value=!!result.removed;reason.value='';decision.value='';confirm.value=false;requestId=crypto.randomUUID();notice.value=''}
function open(next:NonNullable<typeof target.value>){void run(()=>context(next))}
function back(){if(busy.value)return;target.value=null;confirm.value=false;error.value='';void run(()=>load())}
function changedInput(){confirm.value=false;requestId=crypto.randomUUID()}
async function submit(){if(!target.value||!confirm.value)return;const selected={...target.value},key=requestId;await props.request('admin.action',{...selected,requestId:key,decision:decision.value,reason:reason.value.trim()});if(!alive)return;emit('changed');target.value=null;confirm.value=false;notice.value='处理已完成，操作记录已保存';await load()}
function date(value:string){return new Date(value).toLocaleString('zh-CN',{hour12:false})}
onMounted(()=>{void run(()=>props.initialTarget?context(props.initialTarget):load())});
</script>
<template>
 <section class="admin-center" aria-label="社区管理中心" :aria-busy="busy">
  <div class="admin-heading"><ShieldCheck :size="24"/><div><h2>管理中心</h2><p>查看上下文，再做处理</p></div><button aria-label="刷新管理页面" :disabled="busy" @click="run(()=>target?context(target):load())"><RefreshCw :size="20"/></button></div>
  <p v-if="error" class="admin-error" role="alert">{{error}}<button :disabled="busy" @click="run(()=>target?context(target):load())">重新加载</button></p><p v-if="notice" role="status" class="admin-notice">{{notice}}</p><p v-if="busy" role="status" class="admin-muted">正在处理，请稍候…</p>
  <template v-if="!target">
   <nav aria-label="管理栏目"><button v-for="(name,key) in {reports:'待处理',content:'内容管理',history:'操作记录'}" :key="key" :aria-pressed="tab===key" :disabled="busy" @click="change(key)">{{name}}</button></nav>
   <template v-if="tab==='reports'"><p class="admin-caption">待处理举报 · {{reports.length}}{{reports.length===50?'（当前最早 50 条）':''}}</p><p v-if="!busy&&!reports.length" class="admin-empty">暂无待处理举报</p><button v-for="r in reports" :key="r.id" class="admin-row" :disabled="busy" @click="open({postId:r.postId,commentId:r.commentId,reportId:r.id,reportReason:r.reason})"><div><small>{{r.commentId?'评论举报':'帖子举报'}} · {{date(r.createdAt)}}</small><strong>{{r.body}}</strong><p>举报原因：{{r.reason}}</p></div><ChevronRight :size="18"/></button></template>
   <template v-else-if="tab==='content'"><form class="admin-search" @submit.prevent="run(()=>load())"><Search :size="18"/><input v-model="query" aria-label="搜索帖子内容" maxlength="80" placeholder="搜索标题或正文" :disabled="busy"/><button :disabled="busy">搜索</button></form><p class="admin-caption">按发布时间排列 · 点开帖子可管理评论</p><p v-if="!busy&&!posts.length" class="admin-empty">没有找到相关帖子</p><button v-for="p in posts" :key="p.id" class="admin-row" :disabled="busy" @click="open({postId:p.id})"><div><small>{{p.author.name}} · {{date(p.createdAt)}}{{p.locked?' · 已暂停回复':''}}</small><strong>{{p.title||p.body}}</strong><p v-if="p.title">{{p.body}}</p></div><ChevronRight :size="18"/></button></template>
   <template v-else><p class="admin-caption">记录处理人、操作对象和独立处理理由</p><p v-if="!busy&&!history.length" class="admin-empty">暂无操作记录</p><article v-for="h in history" :key="h.id" class="admin-record"><small>{{h.operator||'历史管理员'}} · {{date(h.createdAt)}}</small><h3>{{labels[h.action]||h.action}} · {{h.commentId?'评论':h.postId?'帖子':'账号'}}</h3><p>{{h.reason}}</p><button v-if="h.postId" :disabled="busy" @click="open({postId:h.postId,commentId:h.commentId})">查看操作对象<ChevronRight :size="16"/></button></article></template>
   <button v-if="more" class="admin-more" :disabled="busy" @click="run(()=>load(true))">加载更多</button>
  </template>
  <template v-else>
   <button class="admin-back" :disabled="busy" @click="back"><ArrowLeft :size="18"/>返回管理列表</button>
   <div v-if="target.reportReason" class="admin-report"><small>举报人的反馈</small><p>{{target.reportReason}}</p></div>
   <p v-if="removed" class="admin-empty">原帖已删除，配图可能已清理。仍可将举报标记为无需处理。</p>
   <article v-if="post" class="admin-context"><small>{{post.author.name}} · {{date(post.createdAt)}}{{post.locked?' · 已暂停回复':''}}</small><h3 v-if="post.title">{{post.title}}</h3><p>{{post.body}}</p><div class="admin-images"><a v-for="image in post.images||[]" :key="image.id" :href="image.url||undefined" target="_blank" rel="noopener noreferrer"><img v-if="image.url" :src="image.url" alt="被管理帖子的配图"/><span v-else>配图暂不可用</span></a></div></article>
   <article v-if="parentComment" class="admin-report"><small>这条评论回复的内容 · {{parentComment.author.name}}</small><p>{{parentComment.body}}</p></article>
   <article v-if="comment" class="admin-report"><small>正在处理的评论 · {{comment.author.name}}</small><p>{{comment.body}}</p><div class="admin-images"><a v-for="image in comment.images||[]" :key="image.id" :href="image.url||undefined" target="_blank" rel="noopener noreferrer"><img v-if="image.url" :src="image.url" alt="被管理评论的配图"/></a></div></article>
   <form class="admin-decision" @submit.prevent="confirm?run(submit):(confirm=true)"><h3>处理决定</h3><label>选择操作<select v-model="decision" aria-label="选择操作" required :disabled="busy" @change="changedInput"><option value="" disabled>请选择</option><template v-for="(name,key) in labels" :key="key"><option v-if="key!=='grant_moderator'&&(!removed||key==='dismiss')&&(!['ban','dismiss'].includes(key)||target.reportId)" :value="key">{{name}}</option></template></select></label><label>处理理由<textarea v-model="reason" required minlength="2" maxlength="300" rows="3" :disabled="busy" placeholder="填写你的判断，不会自动沿用举报理由" @input="changedInput"/></label><p v-if="decision==='remove'" class="admin-danger">删除将清理内容和配图，当前版本不支持恢复。</p><p v-if="decision==='lock'||decision==='unlock'" class="admin-muted">此操作影响整篇帖子，包含其下所有评论的回复入口。</p><div v-if="confirm" class="admin-confirm" role="alert"><strong>确认{{labels[decision]}}？</strong><p>{{reason}}</p><button type="button" :disabled="busy" @click="confirm=false">返回修改</button></div><button class="admin-primary" :disabled="busy||!decision||reason.trim().length<2">{{confirm?'确认执行':'核对处理内容'}}</button></form>
   <section v-if="!target.commentId&&comments.length" class="admin-comments"><h3>最近上下文 · 最早 {{comments.length}} 条评论</h3><button v-for="c in comments" :key="c.id" class="admin-row" :disabled="busy||c.deleted" @click="open({postId:target.postId,commentId:c.id})"><div><small>{{c.author.name}}{{c.replyTo?' · 楼中楼回复':''}}</small><p>{{c.body}}</p></div><ChevronRight :size="18"/></button><p class="admin-muted">更多评论可在社区帖子中选择“管理此内容”。</p></section>
  </template>
 </section>
</template>
<style scoped>
.admin-center{color:var(--color-text);padding:16px 0 28px;overflow-wrap:anywhere}.admin-heading{display:flex;align-items:center;gap:12px;padding-bottom:20px}.admin-heading>svg{color:var(--color-primary)}.admin-heading>div{flex:1}.admin-heading h2{font-size:22px}.admin-heading p,.admin-caption,.admin-muted{font-size:12px;color:var(--color-muted);line-height:1.8}.admin-heading button{width:44px;height:44px}.admin-center button{min-height:44px}.admin-center nav{display:flex;border-bottom:1px solid var(--color-divider);gap:8px}.admin-center nav button{flex:1;font-size:14px;color:var(--color-muted);border-bottom:2px solid transparent}.admin-center nav button[aria-pressed=true]{color:var(--color-primary-strong);border-color:var(--color-primary)}.admin-caption{margin:16px 0 8px}.admin-row{display:flex;width:100%;text-align:left;align-items:center;gap:12px;border-bottom:1px solid var(--color-divider);padding:18px 0}.admin-row>div{flex:1;min-width:0}.admin-row small,.admin-record small,.admin-context small,.admin-report small{display:block;font-size:11px;color:var(--color-muted);line-height:1.8}.admin-row strong{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;font-size:15px;line-height:1.8;margin:5px 0}.admin-row p{font-size:13px;line-height:1.8;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}.admin-search{display:flex;align-items:center;gap:8px;background:var(--color-bg);border-radius:10px;padding:4px 10px;margin-top:16px}.admin-search input{flex:1;min-width:0;border:0;background:none;min-height:44px}.admin-search button{color:var(--color-primary);padding:0 8px}.admin-empty{text-align:center;padding:32px 12px;font-size:14px;color:var(--color-muted)}.admin-record{padding:18px 0;border-bottom:1px solid var(--color-divider)}.admin-record h3{margin:5px 0;font-size:15px}.admin-record p{font-size:14px;white-space:pre-wrap}.admin-record button,.admin-back{display:flex;align-items:center;gap:8px;color:var(--color-primary);font-size:13px}.admin-back{margin-bottom:12px}.admin-context,.admin-report{padding:16px 0;border-bottom:1px solid var(--color-divider)}.admin-context h3{font-size:20px;margin:8px 0}.admin-context p,.admin-report p{white-space:pre-wrap;line-height:1.85;font-size:15px}.admin-report{background:var(--color-highlight);padding:14px;border-radius:10px;margin-bottom:12px}.admin-images{display:flex;gap:8px;overflow-x:auto;margin-top:12px}.admin-images a{flex:0 0 112px}.admin-images img{width:112px;height:112px;object-fit:contain;background:var(--color-bg);border-radius:8px}.admin-decision{padding:20px 0}.admin-decision h3{font-size:16px}.admin-decision label{display:block;margin:14px 0;font-size:13px}.admin-decision select,.admin-decision textarea{display:block;width:100%;font:inherit;color:var(--color-text);background:var(--color-bg);border:1px solid var(--color-border);border-radius:8px;padding:12px;margin-top:7px;min-height:44px}.admin-danger,.admin-error{color:var(--color-danger);font-size:13px;line-height:1.8}.admin-error,.admin-notice{padding:12px;background:var(--color-highlight);border-radius:10px}.admin-error button{display:block;color:var(--color-primary)}.admin-notice{font-size:13px}.admin-primary{width:100%;background:var(--color-primary);color:var(--color-raised);border-radius:10px;margin-top:14px;font-size:14px;font-weight:600}.admin-confirm{padding:14px;background:var(--color-highlight);border:1px solid var(--color-border);border-radius:10px;margin-top:12px}.admin-confirm p{white-space:pre-wrap}.admin-confirm button{color:var(--color-primary)}.admin-more{display:block;width:100%;color:var(--color-primary);margin-top:12px}.admin-comments h3{font-size:14px}.admin-center button:focus-visible,.admin-center a:focus-visible{outline:2px solid var(--color-primary);outline-offset:2px}
</style>
